-- The guest's pay commands and the hold (#110; D127 3.x, 5.2; design §3–§5). Generated by
-- drizzle-kit, then this comment and the trigger at the end added by hand. No data.
--
-- - `payments.form_values`: what the paying phone's card form needs (e.g. a client secret), held
--   only while the payment is `awaiting_guest`; the check makes the database refuse it in any
--   other state, so the update that leaves `awaiting_guest` must clear it.
-- - `payment_lines.open`: true while its payment is not final. The partial unique index keeps a
--   POS line in one open payment at a time (D127 5.2), which replaces D112's `order_payment` and
--   `bill_payment` leases: both scopes leave `locks_scope` (no code ever took one).
-- - The trigger closes a payment's lines in the statement that settles it, whoever settles it.
-- - `provider_notices.kind` gains `payment`: a change to a payment's hold, which the worker checks.
ALTER TABLE "restro"."locks" DROP CONSTRAINT "locks_scope";--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" DROP CONSTRAINT "provider_notices_kind";--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" ADD COLUMN "open" boolean DEFAULT true NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD COLUMN "form_values" jsonb;--> statement-breakpoint
CREATE UNIQUE INDEX "payment_lines_open_line_unique" ON "restro"."payment_lines" USING btree ("tenant_id","venue_id","pos_line_ref") WHERE "restro"."payment_lines"."open" and "restro"."payment_lines"."pos_line_ref" is not null;--> statement-breakpoint
ALTER TABLE "restro"."locks" ADD CONSTRAINT "locks_scope" CHECK ("restro"."locks"."scope" in ('order_slot', 'payment_table'));--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD CONSTRAINT "payments_form_values" CHECK ("restro"."payments"."form_values" is null or ("restro"."payments"."state" = 'awaiting_guest' and jsonb_typeof("restro"."payments"."form_values") = 'object'));--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" ADD CONSTRAINT "provider_notices_kind" CHECK ("restro"."provider_notices"."kind" in ('payment', 'refund', 'dispute', 'other'));--> statement-breakpoint
CREATE FUNCTION restro.close_payment_lines()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  UPDATE restro.payment_lines
     SET open = false, source = NEW.source, actor = NEW.actor, job_id = NEW.job_id
   WHERE tenant_id = NEW.tenant_id AND payment_id = NEW.id AND open;
  RETURN NULL;
END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION restro.close_payment_lines() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER payments_close_lines AFTER UPDATE OF settled_at ON restro.payments
  FOR EACH ROW WHEN (OLD.settled_at IS NULL AND NEW.settled_at IS NOT NULL)
  EXECUTE FUNCTION restro.close_payment_lines();
